import {
  createContext,
  FC,
  ReactNode,
  useCallback,
  useContext,
  useEffect,
  useMemo,
  useRef,
  useState,
} from 'react';

import { BffResponse } from 'services';

export interface JsonCacheContextValue {
  getCachedView: (key: string) => BffResponse | undefined;
  registerView: (key: string, response: BffResponse) => void;
  getAllViews: () => Record<string, BffResponse>;
  isCacheHit: boolean;
  isStaleHit: boolean;
  shouldRevalidate: boolean;
}

const JsonCacheContext = createContext<JsonCacheContextValue | null>(null);

export interface JsonCacheProviderProps {
  children: ReactNode;
  initialData?: Record<string, BffResponse> | null;
  isStaleHit?: boolean;
  shouldRevalidate?: boolean;
  contextRef?: React.MutableRefObject<JsonCacheContextValue | null>;
}

export const JsonCacheProvider: FC<JsonCacheProviderProps> = ({
  children,
  initialData,
  isStaleHit = false,
  shouldRevalidate = false,
  contextRef,
}) => {
  const [isCacheHit] = useState(
    () => !!initialData && Object.keys(initialData).length > 0,
  );
  const viewsRef = useRef<Record<string, BffResponse>>(initialData ?? {});

  // Mutation-only in-memory buffer: views are registered as each useBffData call
  // completes without triggering provider re-renders (pages may load 13–34 views).
  // Consumers read via getCachedView; the full map is snapshotted once on submit.
  const getCachedView = useCallback(
    (key: string): BffResponse | undefined => viewsRef.current[key],
    [],
  );

  const registerView = useCallback(
    (key: string, response: BffResponse): void => {
      viewsRef.current[key] = response;
    },
    [],
  );

  const getAllViews = useCallback((): Record<string, BffResponse> => {
    // Shallow copy: small map (~dozens of views) snapshotted once at cache submit.
    return { ...viewsRef.current };
  }, []);

  const value = useMemo<JsonCacheContextValue>(
    () => ({
      getCachedView,
      registerView,
      getAllViews,
      isCacheHit,
      isStaleHit,
      shouldRevalidate,
    }),
    [
      getCachedView,
      registerView,
      getAllViews,
      isCacheHit,
      isStaleHit,
      shouldRevalidate,
    ],
  );

  useEffect(() => {
    if (contextRef) {
      contextRef.current = value;
    }
  }, [contextRef, value]);

  return (
    <JsonCacheContext.Provider value={value}>
      {children}
    </JsonCacheContext.Provider>
  );
};

export const useJsonCacheContext = (): JsonCacheContextValue | null =>
  useContext(JsonCacheContext);

const formatCacheParamValue = (value: unknown): string => {
  if (typeof value === 'object' && value !== null) {
    try {
      return JSON.stringify(value);
    } catch {
      console.error('Failed to stringify cache param value', value);
    }
  }
  return typeof value === 'object' ? '' : String(value);
};

const stableParamsKey = (params: Record<string, unknown>): string =>
  Object.keys(params)
    .sort((a, b) => a.localeCompare(b))
    .map((key) => `${key}:${formatCacheParamValue(params[key])}`)
    .join('|');

export const buildViewCacheKey = (
  id: string,
  params: Record<string, unknown>,
): string => {
  try {
    return `${id}::${JSON.stringify(params)}`;
  } catch {
    return `${id}::${stableParamsKey(params)}`;
  }
};
